 1 | // SPDX-License-Identifier: AGPL-3.0
 2 | pragma solidity ^0.8.21;
 3 | 
 4 | import "@solmate/tokens/ERC4626.sol";
 5 | import "@solmate/utils/FixedPointMathLib.sol";
 6 | import "@solmate/utils/ReentrancyGuard.sol";
 7 | import "@solmate/utils/SafeTransferLib.sol";
 8 | 
 9 | import "../../interfaces/pools/IBaseInterestAllocator.sol";
10 | import "../../interfaces/pools/IFeeManager.sol";
11 | import "../../interfaces/pools/IPool.sol";
12 | import "../../interfaces/pools/IPoolWithWithdrawalQueues.sol";
13 | import "../../interfaces/pools/IPoolOfferHandler.sol";
14 | import "../loans/LoanManager.sol";
15 | import "../utils/Interest.sol";
16 | import "./WithdrawalQueue.sol";
17 | 
18 | /// @title Pool
19 | /// @author Florida St
20 | /// @notice A pool is an implementation of an ERC4626 that allows LPs to deposit capital that will
21 | ///         be used to fund loans (the underwriting rules are handled by the `PoolUnderwriter`). Idle
22 | ///         capital is managed by a BaseInterestAllocator to make sure that the majority of the
23 | ///         assets are earning some yield. This BaseInterestAllocator is meant to take a base yield
24 | ///         with low risk/high liquidity.
25 | ///         Withdrawals happen in two steps. First the users calls `withdraw`/`reedeem` which will give them,
26 | ///         an NFT that will represent a fraction of the value of the pool at the moment of the activation
27 | ///         of the following `WithdrawalQueue`. When a `WithdrawalQueue` is deployed, it will represent a fraction
28 | ///         of the pool's value given by ratio between the total amount of shares pending withdrawal and the total number
29 | ///         of shares. The value of the pool is defined by the amount of idle assets, the outstanding value of loans issued
30 | ///         after the deployment of the previous WithdrawalQueue, and a fraction of the outstanding value of all loans
31 | ///         belonging to previous WithdrawalQueues.
32 | ///         Capital available for withdrawal is managed through a claim process to keep the cost of repayments/refinances
33 | ///         to a minimum. The burden of it is put on the user deploying the queues as well as claiming later.
34 | contract Pool is ERC4626, InputChecker, IPool, IPoolWithWithdrawalQueues, LoanManager, ReentrancyGuard {
35 |     using EnumerableSet for EnumerableSet.AddressSet;
36 |     using FixedPointMathLib for uint128;
37 |     using FixedPointMathLib for uint256;
38 |     using Interest for uint256;
39 |     using SafeTransferLib for ERC20;
40 | 
41 |     /// @dev Precision used for principal accounting.
42 |     uint80 public constant PRINCIPAL_PRECISION = 1e20;
43 | 
44 |     uint256 private constant _SECONDS_PER_YEAR = 31536000;
45 | 
46 |     /// @dev 10000 BPS = 100%
47 |     uint16 private constant _BPS = 10000;
48 | 
49 |     /// @dev Max bonus for reallocating.
50 |     uint16 private _MAX_BONUS = 500;
51 | 
52 |     /// @dev Fees accumulated by the vault.
53 |     uint256 public getCollectedFees;
54 |
